function evidence = f90_xfluid07_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XFLUID07_EXTRACT_CANDIDATE_EVIDENCE Candidate speed-control replay.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot,sharedRoot]=localRoots("F90-XFLUID-07");
addpath(sharedRoot,"-begin");cleanup=onCleanup(@()rmpath(sharedRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xfluid07-evidence.v1", ...
    "task_id","F90-XFLUID-07","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@(~,~)double(official.simulation.stop_time_s), ...
    "postprocess",@localPostprocess,"static_audit",@localAudit, ...
    "evidence_sample_s",0.05);
evidence=simuverity_run_candidate_evidence(candidatePath,outDir,spec);
end
function rows=localOutputs
rows=localRows(["speed_control","hydraulic_state","drivetrain_effort"],[3 4 4]);
end
function inputs=localInputs(s,~)
inputs=struct("distance_breakpoints_m",double(s.distance_breakpoints_m(:)), ...
    "target_velocity_kph",double(s.target_velocity_kph(:)), ...
    "engine_speed_rpm",double(s.engine_speed_rpm));
end
function requested=localRequested(s,~),requested=rmfield(s,"id");end
function row=localPostprocess(row,outputs,scenario,~)
t=double(outputs.time_s(:));speedControl=double(outputs.speed_control);
hydraulic=double(outputs.hydraulic_state);effort=double(outputs.drivetrain_effort);
target=speedControl(:,1)/3.6;speed=speedControl(:,2)/3.6;
dispValue=speedControl(:,3);pressure=hydraulic(:,1);pumpFlow=hydraulic(:,2);
frontSpeed=hydraulic(:,3);rearSpeed=hydraulic(:,4);
engine=effort(:,1);pumpTorque=effort(:,2);
frontTorque=effort(:,3);rearTorque=effort(:,4);
late=t>=max(t(end)-15,0.8*t(end));tracking=t>=5 & target>=0.2;
if nnz(tracking)<10,tracking=true(size(t));end
error=speed-target;rmse=sqrt(mean(error(tracking).^2));
nrmse=rmse/max(sqrt(mean(target(tracking).^2)),0.5);
r2=1-sum(error(tracking).^2)/ ...
    max(sum((target(tracking)-mean(target(tracking))).^2),eps);
frontFinal=median(frontSpeed(late));rearFinal=median(rearSpeed(late));
frontTorqueRms=sqrt(mean(frontTorque(late).^2));
rearTorqueRms=sqrt(mean(rearTorque(late).^2));
% The public contract omits branch flow. Hydrostatic continuity makes
% speed mismatch the observable, implementation-neutral branch proxy.
frontFlowRms=abs(frontFinal)*abs(median(pumpFlow(late)))/ ...
    max(abs(frontFinal)+abs(rearFinal),eps);
rearFlowRms=abs(rearFinal)*abs(median(pumpFlow(late)))/ ...
    max(abs(frontFinal)+abs(rearFinal),eps);
inputPower=abs(engine*(2*pi/60).*pumpTorque)/1000;
outputPower=abs(frontSpeed*(2*pi/60).*frontTorque)/1000+ ...
    abs(rearSpeed*(2*pi/60).*rearTorque)/1000;
lateInput=mean(inputPower(late));lateOutput=mean(outputPower(late));
targetFinal=median(target(late));speedFinal=median(speed(late));
pumpRange=max(dispValue)-min(dispValue);
row.metrics=struct( ...
    "requested_profile_max_mps",max(double(scenario.target_velocity_kph))/3.6, ...
    "requested_profile_final_mps",double(scenario.target_velocity_kph(end))/3.6, ...
    "requested_engine_speed_rpm",double(scenario.engine_speed_rpm), ...
    "requested_implement_depth_cm",double(scenario.implement_depth_cm), ...
    "requested_soil_cohesion_kpa",double(scenario.soil_cohesion_kpa), ...
    "requested_tire_inflation_kpa",double(scenario.tire_inflation_kpa), ...
    "final_target_speed_mps",targetFinal,"final_tractor_speed_mps",speedFinal, ...
    "tracking_rmse_mps",rmse,"tracking_mae_mps",mean(abs(error(tracking))), ...
    "tracking_normalized_rmse",nrmse,"tracking_r2",r2, ...
    "maximum_absolute_tracking_error_mps",max(abs(error(tracking))), ...
    "late_tracking_rmse_mps",sqrt(mean(error(late).^2)), ...
    "final_tracking_relative_error",abs(speedFinal-targetFinal)/ ...
        max(abs(targetFinal),0.5), ...
    "final_engine_speed_rpm",median(engine(late)), ...
    "final_pump_displacement_cm3_rev",median(dispValue(late)), ...
    "final_implement_depth_cm",double(scenario.implement_depth_cm), ...
    "minimum_tractor_speed_mps",min(speed), ...
    "maximum_loop_pressure_bar",max(pressure), ...
    "late_pressure_ripple_fraction",std(pressure(late))/ ...
        max(abs(mean(pressure(late))),1e-6), ...
    "late_mean_input_power_kw",lateInput,"late_mean_output_power_kw",lateOutput, ...
    "late_transmission_loss_kw",max(lateInput-lateOutput,0), ...
    "late_energy_efficiency",lateOutput/max(lateInput,eps), ...
    "front_motor_speed_rpm",frontFinal,"rear_motor_speed_rpm",rearFinal, ...
    "front_motor_torque_rms_nm",frontTorqueRms, ...
    "rear_motor_torque_rms_nm",rearTorqueRms, ...
    "front_motor_flow_rms_m3_s",frontFlowRms, ...
    "rear_motor_flow_rms_m3_s",rearFlowRms, ...
    "axle_speed_relative_mismatch",abs(frontFinal-rearFinal)/ ...
        max(max(abs([frontFinal,rearFinal])),1e-6), ...
    "axle_torque_relative_mismatch",abs(frontTorqueRms-rearTorqueRms)/ ...
        max(max(abs([frontTorqueRms,rearTorqueRms])),1e-6), ...
    "axle_flow_relative_mismatch",abs(frontFlowRms-rearFlowRms)/ ...
        max(max(abs([frontFlowRms,rearFlowRms])),1e-9), ...
    "cold_start_rise_time_s",localFirst(t,abs(speed)>=0.9*max(abs(targetFinal),eps)), ...
    "final_command_settling_time_s",localSettling(t,target,speed), ...
    "late_vehicle_speed_cv",std(speed(late))/ ...
        max(abs(mean(speed(late))),1e-6), ...
    "negative_vehicle_speed_fraction",mean(speed<-0.02), ...
    "pump_displacement_range_cm3_rev",pumpRange, ...
    "pump_saturation_fraction",mean(dispValue<=10.5|dispValue>=56.5), ...
    "error_to_pump_abs_correlation",localCorr(target(tracking)-speed(tracking), ...
        dispValue(tracking)), ...
    "pressure_to_pump_torque_abs_correlation", ...
        localCorr(pressure(tracking),abs(pumpTorque(tracking))), ...
    "finite_fraction",mean(isfinite([speedControl,hydraulic,effort]),"all"), ...
    "candidate_public_branch_flow_proxy","speed_weighted_pump_flow");
row.outputs=outputs;row.valid=row.output_contract.all_required_pass && ...
    row.metrics.finite_fraction>=0.999999;
end
function value=localFirst(t,mask),i=find(mask,1);if isempty(i),value=inf;else,value=t(i);end,end
function value=localSettling(t,target,actual)
error=abs(actual-target);tol=max(0.08*max(abs(target)),0.05);
value=inf;for k=1:numel(t),if all(error(k:end)<=tol),value=t(k);break,end,end
end
function value=localCorr(a,b)
if numel(a)<3||std(a)<1e-12||std(b)<1e-12,value=0;else, ...
    c=corrcoef(a,b);value=abs(c(1,2));end
end
function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
audit=struct("required_products_available",true, ...
    "qualification_basis","public_multiscenario_behavior", ...
    "qualification_deferred_to_offline_public_behavior",true, ...
    "signal_cycle_observed",structure.signal_cycle_present, ...
    "physical_connection_block_count_observation", ...
        structure.physical_connection_block_count);
end
function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear"),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
    rows(k).width=widths(k);end
end
function [taskRoot,sharedRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end
